const input = $json || {};
const workspace_id = input.workspace_id || $env.VF_WORKSPACE_ID;
const required = ['experiment_id', 'video_job_id', 'variant_key'];

if (!workspace_id) throw new Error('VF_CANARY: workspace_id missing');
for (const key of required) {
  if (!input[key]) throw new Error('VF_CANARY: ' + key + ' missing');
}
if (!['control', 'candidate'].includes(input.variant_key)) {
  throw new Error('VF_CANARY: variant_key must be control or candidate');
}

return [{
  json: {
    workspace_id,
    experiment_id: input.experiment_id,
    video_job_id: input.video_job_id,
    variant_key: input.variant_key,
    quality_score: input.quality_score ?? null,
    performance_score: input.performance_score ?? null,
    render_success: input.render_success ?? null,
    metrics: input.metrics || {}
  }
}];

const response = $json || {};
if (response.ok !== true) {
  throw new Error('VF_CANARY: outcome API returned invalid response');
}
return [{
  json: {
    vf_canary_outcome: {
      recorded: true,
      idempotent: response.data?.idempotent === true,
      automatic_promotion: false,
      observation_id: response.data?.observation?.id || null
    }
  }
}];
